self.KB_CONTENT["card:750653"]={"id":"card:750653","ty":"card","sourceId":"750653","title":"『IFRS差異調節表』中的『選擇列印種類 (C1)』為何？","ver":"iGP","topic":"明細表","keywords":["明細表","科目"],"y":"other","answer":"* 分為1.不展統制/明細，2.展至統制帳戶及3.展至明細帳戶三種。* 不展統制/明細：表示依報表格式設定的科目列印。* 展至統制帳戶表示依報表格式設定的科目展至設定科目下的統制帳戶。* 展至明細帳戶表示依報表格式設定的科目展至設定科目下的明細科目。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
