self.KB_CONTENT["field:752624"]={"id":"field:752624","ty":"field","sourceId":"752624","title":"底稿開立方式","ver":"iGP","topic":"","keywords":[],"job":"分錄性質設定-銷貨單","code":"MB004","answer":"* 銷貨單開立傳票方式分為1.逐張及2.彙總兩種開立方式。","file":"fields.jsonl"};
